from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass
from pathlib import Path

from vscode_profiles.errors import CliError

NEWLINE = "\r\n"

HEADER = (
    "# Generated by vscode-profiles --emit-ps1.",
    "# Quit VS Code completely, then run this from an external terminal:",
    "#   pwsh -File {path}",
    "$ErrorActionPreference = 'Stop'",
    "if (Get-Process -Name Code -ErrorAction SilentlyContinue) {",
    "    throw 'VS Code (Code.exe) is running. Quit it and run this script again.'",
    "}",
)


@dataclass(frozen=True)
class EmitScript:
    path: Path
    command: tuple[str, ...]
    comment: str


def ps_quote(value: str) -> str:
    return "'" + value.replace("'", "''") + "'"


def append_command(path: Path, command: Sequence[str], comment: str) -> None:
    """Append one write command to a PowerShell script, creating it with a header first."""
    lines: list[str] = []
    if not path.exists():
        lines.extend(line.replace("{path}", ps_quote(str(path))) for line in HEADER)
    lines.append("")
    lines.append(f"# {comment}")
    lines.append("& " + " ".join(ps_quote(part) for part in command))
    lines.append('if ($LASTEXITCODE -ne 0) { throw "vscode-profiles failed (exit $LASTEXITCODE)" }')
    text = NEWLINE.join(lines) + NEWLINE
    try:
        if path.exists():
            with path.open("a", encoding="utf-8", newline="") as handle:
                handle.write(text)
        else:
            path.write_text(text, encoding="utf-8-sig", newline="")
    except OSError as exc:
        raise CliError(f"could not write script: {path}: {exc}") from exc
